    # Map each 3x3 area to its unique non-background color; zero means none/mixed.
    n = len(grid) // 3
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            block = [grid[i][j] for i in range(r*3, (r+1)*3)
                     for j in range(c*3, (c+1)*3)]
